// Android device panel adb helpers. Generated by ttoken/apply-brand.mjs from ttoken/device/tests/adb.spec.ts; edit it there.
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, win32 } from 'node:path'
import { crc32 } from 'node:zlib'
import { describe, expect, it } from 'vitest'
import {
  AdbUnavailableError, adbRunner, avdProblem, failureText, inputArgs, inputProblem, parseAvds, parseDevices, pngSize, serialProblem,
} from '../src/adb.ts'
import {
  installPlatformTools, PlatformToolsInstallError, platformToolsUrl, resolveExecutable, sdkToolCommands, unzipCommand,
} from '../src/platform-tools.ts'

describe('adb device list', () => {
  it('reads each device after the header, skipping daemon notices and blank lines', () => {
    const text = [
      '* daemon not running; starting now at tcp:5037',
      '* daemon started successfully',
      'List of devices attached',
      'emulator-5554          device product:sdk_gphone64_x86_64 model:Pixel_9 device:emu64xa transport_id:1',
      'R58N12345AB            unauthorized usb:1-1 transport_id:2',
      '192.168.1.5:5555       offline transport_id:3',
      '',
    ].join('\r\n')
    expect(parseDevices(text)).toEqual([
      { serial: 'emulator-5554', state: 'device', model: 'Pixel 9', transport: 'emulator' },
      { serial: 'R58N12345AB', state: 'unauthorized', model: null, transport: 'usb' },
      { serial: '192.168.1.5:5555', state: 'offline', model: null, transport: 'network' },
    ])
  })

  it('lists nothing when no device is attached', () => {
    expect(parseDevices('List of devices attached\n\n')).toEqual([])
  })
})

describe('PNG size', () => {
  it('reads the width and height of a PNG header and refuses other bytes', () => {
    const header = new Uint8Array(24)
    header.set([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])
    const view = new DataView(header.buffer)
    view.setUint32(16, 1080)
    view.setUint32(20, 2400)
    expect(pngSize(header)).toEqual({ width: 1080, height: 2400 })
    expect(pngSize(new TextEncoder().encode('error: device offline, no screenshot'))).toBeUndefined()
  })
})

describe('device input', () => {
  it('accepts whole pixels, bounded swipes, printable text, and keys', () => {
    expect(inputProblem({ kind: 'tap', x: 540, y: 1728 })).toBeNull()
    expect(inputProblem({ kind: 'swipe', fromX: 1, fromY: 2, toX: 3, toY: 4, durationMs: 300 })).toBeNull()
    expect(inputProblem({ kind: 'text', text: 'naufal@tokokopi.id' })).toBeNull()
    expect(inputProblem({ kind: 'key', key: 'back' })).toBeNull()
  })

  it('refuses fractional or negative coordinates, long swipes, and text adb cannot type', () => {
    expect(inputProblem({ kind: 'tap', x: 1.5, y: 2 })).not.toBeNull()
    expect(inputProblem({ kind: 'tap', x: -1, y: 2 })).not.toBeNull()
    expect(inputProblem({ kind: 'swipe', fromX: 1, fromY: 2, toX: 3, toY: 4, durationMs: 60_000 })).not.toBeNull()
    expect(inputProblem({ kind: 'text', text: 'kopi ☕' })).not.toBeNull()
    expect(inputProblem({ kind: 'text', text: '' })).not.toBeNull()
  })

  it('quotes typed text for the device shell and spells spaces as %s', () => {
    expect(inputArgs({ kind: 'text', text: 'it\'s a test; rm' })).toEqual(['shell', 'input', 'text', '\'it\'\\\'\'s%sa%stest;%srm\''])
    expect(inputArgs({ kind: 'tap', x: 10, y: 20 })).toEqual(['shell', 'input', 'tap', '10', '20'])
    expect(inputArgs({ kind: 'key', key: 'recents' })).toEqual(['shell', 'input', 'keyevent', 'KEYCODE_APP_SWITCH'])
  })

  it('accepts adb serials and refuses ones with spaces or shell characters', () => {
    expect(serialProblem('emulator-5554')).toBeNull()
    expect(serialProblem('adb-R58N123-AbCd._adb-tls-connect._tcp')).toBeNull()
    expect(serialProblem('a b')).not.toBeNull()
    expect(serialProblem('x;rm')).not.toBeNull()
    expect(serialProblem('-a')).not.toBeNull()
  })
})

describe('adb failure text', () => {
  it('prefers the first line of standard error, then standard output, then the exit code', () => {
    expect(failureText({ exitCode: 1, stdout: new Uint8Array(), stderr: 'error: device offline\nmore' })).toBe('error: device offline')
    expect(failureText({ exitCode: 1, stdout: new TextEncoder().encode('no devices/emulators found'), stderr: '' }))
      .toBe('no devices/emulators found')
    expect(failureText({ exitCode: 255, stdout: new Uint8Array(), stderr: '' })).toBe('adb exited with code 255')
  })
})

describe('emulators', () => {
  it('reads AVD names and skips the log lines newer emulators print', () => {
    expect(parseAvds('INFO    | Storing crashdata in: /tmp/crash\nPixel_9_API_35\r\nMedium_Phone\n\n')).toEqual(['Pixel_9_API_35', 'Medium_Phone'])
    expect(avdProblem('Pixel_9_API_35')).toBeNull()
    expect(avdProblem('-wipe-data')).not.toBeNull()
    expect(avdProblem('a b')).not.toBeNull()
  })
})

describe('Android SDK tools', () => {
  it('keeps a configured path alone and lists the SDK, package-manager, and installed copies of a bare tool', () => {
    const linux = { env: { ANDROID_HOME: '/sdk' }, platform: 'linux' as const, home: '/home/me', installDirectory: '/data/tools' }
    expect(sdkToolCommands('adb', '/opt/adb', linux)).toEqual(['/opt/adb'])
    expect(sdkToolCommands('adb', 'adb', linux)).toEqual([
      'adb', '/sdk/platform-tools/adb', '/home/me/Android/Sdk/platform-tools/adb', '/data/tools/platform-tools/adb',
    ])
    expect(sdkToolCommands('emulator', 'emulator', linux)).toEqual(['emulator', '/sdk/emulator/emulator', '/home/me/Android/Sdk/emulator/emulator'])
    const windows = {
      env: { LocalAppData: 'C:\\Users\\me\\AppData\\Local', ProgramData: 'C:\\ProgramData' },
      platform: 'win32' as const,
      home: 'C:\\Users\\me',
      installDirectory: 'C:\\Users\\me\\.ttoken-code\\data\\android-platform-tools',
    }
    expect(sdkToolCommands('adb', 'adb', windows)).toEqual([
      'adb',
      'C:\\Users\\me\\AppData\\Local\\Android\\Sdk\\platform-tools\\adb.exe',
      'C:\\Users\\me\\AppData\\Local\\Microsoft\\WinGet\\Links\\adb.exe',
      'C:\\Users\\me\\scoop\\shims\\adb.exe',
      'C:\\ProgramData\\chocolatey\\bin\\adb.exe',
      'C:\\Users\\me\\.ttoken-code\\data\\android-platform-tools\\platform-tools\\adb.exe',
    ])
    expect(sdkToolCommands('adb', 'adb', { env: {}, platform: 'darwin', home: '/Users/me' })).toEqual([
      'adb', '/Users/me/Library/Android/sdk/platform-tools/adb', '/opt/homebrew/bin/adb', '/usr/local/bin/adb',
    ])
  })

  it('resolves a bare name on PATH only to a runnable file, and a path only when it exists', () => {
    const root = mkdtempSync(join(tmpdir(), 'adb-path-'))
    try {
      const bin = join(root, 'bin')
      mkdirSync(bin)
      writeFileSync(join(bin, 'adb'), '#!/bin/sh\n')
      writeFileSync(join(bin, 'notes'), '')
      chmodSync(join(bin, 'adb'), 0o755)
      const env = { PATH: [join(root, 'missing'), bin].join(':') }
      expect(resolveExecutable('adb', env, 'linux')).toBe(join(bin, 'adb'))
      expect(resolveExecutable('notes', env, 'linux')).toBeUndefined()
      expect(resolveExecutable('scrcpy', env, 'linux')).toBeUndefined()
      expect(resolveExecutable(join(bin, 'adb'), {}, 'linux')).toBe(join(bin, 'adb'))
      expect(resolveExecutable(join(root, 'adb'), {}, 'linux')).toBeUndefined()
      expect(resolveExecutable('adb', { Path: 'C:\\nowhere', PATHEXT: '.EXE' }, 'win32')).toBeUndefined()
    } finally {
      rmSync(root, { recursive: true, force: true })
    }
  })

  it('skips candidates that do not resolve and reports adb missing when none does', async () => {
    const node = process.execPath
    const run = adbRunner({
      adbCommands: ['adb', node], timeoutMs: 10_000, maxOutputBytes: 1_024, resolve: command => (command === node ? node : undefined),
    })
    const output = await run(['-e', 'process.stdout.write("listed")'], new AbortController().signal)
    expect(new TextDecoder().decode(output.stdout)).toBe('listed')
    const none = adbRunner({ adbCommands: ['adb', '/sdk/platform-tools/adb'], timeoutMs: 10_000, maxOutputBytes: 1_024, resolve: () => undefined })
    await expect(none(['devices'], new AbortController().signal)).rejects.toThrow(AdbUnavailableError)
    await expect(none(['devices'], new AbortController().signal)).rejects.toThrow('adb is not installed')
  })
})

describe('platform-tools install', () => {
  it('names Google\'s archive and the unpacking program of each Host platform', () => {
    expect(platformToolsUrl('win32')).toBe('https://dl.google.com/android/repository/platform-tools-latest-windows.zip')
    expect(platformToolsUrl('darwin')).toBe('https://dl.google.com/android/repository/platform-tools-latest-darwin.zip')
    expect(platformToolsUrl('linux')).toBe('https://dl.google.com/android/repository/platform-tools-latest-linux.zip')
    expect(platformToolsUrl('aix')).toBeUndefined()
    expect(unzipCommand('a.zip', 'out', { SystemRoot: 'D:\\Windows' }, 'win32')).toEqual({
      command: win32.join('D:\\Windows', 'System32', 'tar.exe'), args: ['-xf', 'a.zip', '-C', 'out'],
    })
    expect(unzipCommand('a.zip', 'out', {}, 'darwin')).toEqual({ command: '/usr/bin/tar', args: ['-xf', 'a.zip', '-C', 'out'] })
    expect(unzipCommand('a.zip', 'out', {}, 'linux')).toEqual({ command: 'unzip', args: ['-q', 'a.zip', '-d', 'out'] })
  })

  const unzipAvailable = resolveExecutable('unzip') !== undefined
  it.skipIf(!unzipAvailable)('unpacks the archive into the directory and replaces an earlier copy', async () => {
    const root = mkdtempSync(join(tmpdir(), 'platform-tools-'))
    try {
      const archive = (body: string) => storedZip([
        { name: 'platform-tools/', data: new Uint8Array(), mode: 0o40755 },
        { name: 'platform-tools/adb', data: new TextEncoder().encode(body), mode: 0o100755 },
      ])
      const serve = (bytes: Uint8Array<ArrayBuffer>): typeof fetch => async () => await Promise.resolve(new Response(bytes))
      const install = { directory: root, timeoutMs: 30_000, platform: 'linux' as const, env: process.env }
      const adb = await installPlatformTools({ ...install, fetch: serve(archive('first')) }, new AbortController().signal)
      expect(adb).toBe(join(root, 'platform-tools', 'adb'))
      expect(statSync(adb).mode & 0o111).not.toBe(0)
      await installPlatformTools({ ...install, fetch: serve(archive('second')) }, new AbortController().signal)
      expect(readFileSync(adb, 'utf8')).toBe('second')
      const empty = storedZip([{ name: 'platform-tools/', data: new Uint8Array(), mode: 0o40755 }])
      await expect(installPlatformTools({ ...install, fetch: serve(empty) }, new AbortController().signal)).rejects.toThrow('The archive holds no adb')
      expect(readFileSync(adb, 'utf8')).toBe('second')
      const missing: typeof fetch = async () => await Promise.resolve(new Response('gone', { status: 404 }))
      await expect(installPlatformTools({ ...install, fetch: missing }, new AbortController().signal))
        .rejects.toThrow(PlatformToolsInstallError)
      expect(existsSync(join(root, 'platform-tools', 'adb'))).toBe(true)
    } finally {
      rmSync(root, { recursive: true, force: true })
    }
  })
})

/** 1 January 2026 as a DOS date, the modification date of every test archive entry. */
const DOS_DATE = ((2026 - 1980) << 9) | (1 << 5) | 1

/** One file or directory of a test archive. */
interface ZipEntry {
  readonly name: string
  readonly data: Uint8Array
  /** Unix mode with its file-type bits, kept in the entry's external attributes. */
  readonly mode: number
}

/**
 * Build an uncompressed zip archive whose entries carry Unix modes, as Google's archives do.
 * @param entries - files and directories in archive order.
 * @returns the archive bytes.
 */
function storedZip(entries: readonly ZipEntry[]): Uint8Array<ArrayBuffer> {
  const locals: Buffer[] = []
  const centrals: Buffer[] = []
  let offset = 0
  for (const entry of entries) {
    const name = Buffer.from(entry.name, 'utf8')
    const checksum = crc32(entry.data)
    const local = Buffer.alloc(30)
    local.writeUInt32LE(0x04034b50, 0)
    local.writeUInt16LE(20, 4)
    local.writeUInt16LE(DOS_DATE, 12)
    local.writeUInt32LE(checksum, 14)
    local.writeUInt32LE(entry.data.byteLength, 18)
    local.writeUInt32LE(entry.data.byteLength, 22)
    local.writeUInt16LE(name.byteLength, 26)
    locals.push(local, name, Buffer.from(entry.data))
    const central = Buffer.alloc(46)
    central.writeUInt32LE(0x02014b50, 0)
    central.writeUInt16LE(0x0314, 4)
    central.writeUInt16LE(20, 6)
    central.writeUInt16LE(DOS_DATE, 14)
    central.writeUInt32LE(checksum, 16)
    central.writeUInt32LE(entry.data.byteLength, 20)
    central.writeUInt32LE(entry.data.byteLength, 24)
    central.writeUInt16LE(name.byteLength, 28)
    central.writeUInt32LE((entry.mode << 16) >>> 0, 38)
    central.writeUInt32LE(offset, 42)
    centrals.push(central, name)
    offset += local.byteLength + name.byteLength + entry.data.byteLength
  }
  const directory = Buffer.concat(centrals)
  const end = Buffer.alloc(22)
  end.writeUInt32LE(0x06054b50, 0)
  end.writeUInt16LE(entries.length, 8)
  end.writeUInt16LE(entries.length, 10)
  end.writeUInt32LE(directory.byteLength, 12)
  end.writeUInt32LE(offset, 16)
  return Buffer.concat([...locals, directory, end])
}
